+	int value;
+	if(offset<2) value=seibu_soundlatch_r(offset);
+	else if(offset==2) value=seibu_main_data_pending_r(0);
+	else value=readinputport(5);
+	r2_debug_sound_access(0x4010+offset,value,0);
+	return value;
+}
